-- BrandDesk is HQ with a friendly layout: the Blueprint tab, Signal, People, the 100 promise (LOCKED by Sean 2026-11-04: "lock it").
-- Concept session with V. Canon canon-branddesk-blueprint-signal; records go on playbook branddesk-production-wing (brand lesaruss-hq).
-- Sean's own system, found 2026-11-04 in the shared drive (02 Frameworks & Systems), replaces any EOS wording:
-- Lesaruss Blueprint (Idea > Brand > Platform > Movement), Launch Architect Method, Blueprint Score, 4 Levels, 90 Day Action Plan, weekly huddles, Feedback Loop.
insert into public.knowledge_records (slug, title, category, subcategory, status, owner, always_load, load_priority, tags, version, created_by, updated_by, change_summary, body)
select 'canon-branddesk-blueprint-signal',
  'BrandDesk: tabs, the Blueprint, Signal, People and the 100 promise (LOCKED by Sean 2026-11-04)',
  'decisions', 'business', 'active', 'sar', false, 40,
  array['lesaruss','branddesk','blueprint','signal','people','blueprint-score','lesaruss-ai'], 1, 'v', 'v',
  'Locked by Sean ("lock it") after a concept session with V and Logan.',
  jsonb_build_object(
    'why', 'Sean: "I think the brand desk is the HQ, just with a more user-friendly layout... everything is in the brand desk." A client who joins LESARUSS.ai logs in, sees their brand desk, and it tells them exactly what to do; their team can log in and follow it, or we do it.',
    'tabs', 'A brand in BrandDesk: Overview, Brand kit, Blueprint (was Plan), Social, People (new: communications, then the team and its health), Signal (was Web: Web plus Google Search Console, page speed, tag manager and the technical fixes), Insights (everything tabulated: analytics, spend, podcast; it feeds the Blueprint). A Finance tab (P&L, in and out) is noted for later and is not part of the Blueprint.',
    'blueprint', 'The Blueprint is the one home for what we are doing and how: About, Playbooks and guides (one list; Playbooks | Guides | All; a playbook opens in place, a guide opens in a new window; each guide has a playbook behind it, the plan, and a guide with none says No playbook yet), the Calendar (today''s marketing plan engine, as a view), Done, and Ideas (the Feedback Loop). It answers the spec Sean locked on 2026-09-14 (About, Playbooks, Completed Tasks).',
    'own_system', 'Sean''s own system, not EOS: the Lesaruss Blueprint Framework (Idea > Brand > Platform > Movement; the 7 Stage Brand Creation Map, the 10 Asset, 35 Asset and 50 Movement Asset systems), the Blueprint Intake, the Blueprint Score, the Feedback Loop, and the Launch Architect Method (Clarify, Architect, Build, Activate, Expand; 7 steps; a 90 Day Action Plan run with weekly huddles) with its 4 Levels: Launch Ready, Growth Ready, Infrastructure Ready (Blueprint + Operating System + Dashboard), Movement Ready. Sources: the shared drive 02 Frameworks & Systems (March 2026); the raw EOS draft for K12 Unlocked (August 2025) is where it began. Use these names; no EOS trademark words on client pages.',
    'blueprint_score', 'The Blueprint Score is the health score, 0 to 100, fed by Signal and Insights. The 4 Levels are the sorter and each client''s status on the master console.',
    'the_100_promise', 'Only on the managed subscription (the $500 a month tier), where the website is on our platform and we control the template, so what blocks 100 is never built in. DIY is a HubSpot-style tool: they plug their own things in and see their scores, with no promise. We test our own brands at 100 first; where we cannot get to 100 we do not make the promise. Everything we control is at 100, every fixable issue is fixed on a schedule (daily, weekly or monthly by plan), a short report says what was done, and anything stopping 100 is listed with a plain reason and what we need.',
    'auto_fix', 'Read-only first. Then auto-fix only the safe classes (redirects, titles and descriptions, sitemap, image size, alt text) on sites we host, each fix logged with an undo like listing edits.',
    'concierge', 'Managed clients get seasonal prompts months ahead by what they sell ("start your Thanksgiving menu, the guide deadline is the 15th"), membership points toward services, and our team helping produce their events. It also brings people to our own events and platform.',
    'people_health', 'A team health score and leaderboard like BCPS Marcom, judged on the work (tasks done, on time), visible to the owner and each person sees their own. Contractors are judged on deliverables, never hours or methods.',
    'master_console', 'In the LESARUSS HQ brand desk: a grid of every client with logo, Blueprint Score and Level, our own brands first as the prototype. A custom master console for a chain (every store from one place) is a separate custom project, not designed for now.',
    'build_order', '1. Rename Plan to Blueprint and add the playbooks and guides list (Vegans Explore first, read-only, then the filters and sorter, then other brands). 2. Signal, read-only (connect Search Console first: it is not connected today). 3. Auto-fix on sites we host. 4. Scorecard (Blueprint Score from Signal and Insights) feeding the Blueprint. 5. People (communications through the outreach engine, then team and health). 6. A client''s own login on LESARUSS.ai. Our own brands first at every step.',
    'open', 'Which guides count outside Vegans Explore (LESARUSS.ai, BCPS); default Vegans Explore only for the first pass. Whether Plan keeps a redirect (default yes).',
    'playbook', 'branddesk-production-wing')
where not exists (select 1 from public.knowledge_records where slug = 'canon-branddesk-blueprint-signal');

insert into public.playbook_records (slug, brand_slug, author, body, source, kind)
select 'branddesk-production-wing', 'lesaruss-hq', 'V',
  'branddesk-production-wing: tabs, Blueprint, Signal, People and the 100 promise. LOCKED by Sean 2026-11-04 ("lock it"; canon canon-branddesk-blueprint-signal; write-up docs/proposals/branddesk-blueprint-signal.md). BrandDesk is HQ with a friendlier layout. Tabs: Overview, Brand kit, Blueprint (was Plan), Social, People, Signal (was Web), Insights. Blueprint holds About, the Playbooks and guides list (playbook opens in place, guide in a new window, each guide has its playbook), Calendar, Done, Ideas. Sean''s own system replaces EOS (Lesaruss Blueprint, Launch Architect Method, Blueprint Score, 4 Levels, 90 Day Action Plan, weekly huddles, Feedback Loop; found in the shared drive 02 Frameworks & Systems). The 100 promise is only for the managed subscription (the $500 a month tier, site on our platform); DIY gets scores and no promise. Auto-fix: safe classes, sites we host, logged with undo. People health judged on deliverables. Master console of clients by Level and Score; chain-scale consoles are custom projects. Finance tab noted for later. Build order: rename and list, Signal read-only (Search Console not connected yet), auto-fix, Scorecard, People, client login on LESARUSS.ai. Nothing built yet.',
  'text', 'decision'
where not exists (select 1 from public.playbook_records where slug = 'branddesk-production-wing' and body like 'branddesk-production-wing: tabs, Blueprint, Signal%');
